  "$id": "poly/m3/host.map.schema.json",
  "title": "host.map.json: how the generated adapter drives a poly module (S90)",
  "type": "object",
  "required": ["module", "instances", "methods", "queries"],
  "additionalProperties": false,
  "properties": {
    "module": { "type": "string", "description": "The poly module the adapter loads." },
    "instances": {
      "type": "object",
      "description": "Each instance the host creates, by name: its machine, and whether it is created at start or by a method (keyed by one of that method's arguments).",
      "additionalProperties": {
        "type": "object",
        "required": ["machine"],
        "additionalProperties": false,
        "properties": {
          "machine": { "type": "string" },
          "createdBy": { "type": "string", "description": "A method name; absent for an instance created when the host is created." },
          "keyArgument": { "type": "string", "description": "The argument of createdBy that names the instance." },
          "init": { "type": "object", "description": "Initial field values, addresses written as instance names." }
        }
      }
    },
    "methods": {
      "type": "object",
      "description": "Each host method: the instance it targets, the action it dispatches, and each action parameter's source argument.",
      "additionalProperties": {
        "type": "object",
        "required": ["instance", "action"],
        "additionalProperties": false,
        "properties": {
          "instance": { "type": "string", "description": "An instance name, the name of a family of instances a method creates, or $arg:<name> for an argument that names an instance created with the host." },
          "machine": { "type": "string", "description": "With $arg:<name>: the machine of the instances the argument may name." },
          "key": { "type": "string", "description": "For a family: $arg:<name>, the argument that names the member." },
          "action": { "type": "string" },
          "params": { "type": "object", "additionalProperties": { "type": "string", "description": "$arg:<name>, or a constant." } },
          "returns": { "enum": ["verdict", "state", "nothing"], "description": "verdict (the default): { ok: true } or { ok: false, reason }." }
        }
      }
    },
    "queries": {
      "type": "object",
      "description": "Each host query: the instance it reads and the fields it returns, renamed as the interface names them.",
      "additionalProperties": {
        "type": "object",
        "required": ["instance", "fields"],
        "additionalProperties": false,
        "properties": {
          "instance": { "type": "string", "description": "An instance name, the name of a family, or $arg:<name> for an argument that names an instance created with the host." },
          "machine": { "type": "string", "description": "With $arg:<name>: the machine of the instances the argument may name." },
          "key": { "type": "string", "description": "For a family: $arg:<name>, the argument that names the member." },
          "fields": { "type": "object", "additionalProperties": { "type": "string" } }
        }
      }
    }
  }
}

