import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const fresh = async () => (await createHost()) as any;

test('authorize, approve, capture, refund', async () => {
  const h = await fresh();
  assert.deepEqual(await h.capture('p', 1), { ok: false, reason: 'unknown' });
  assert.equal(await h.payment('p'), null);
  assert.equal((await h.authorize('p', 3)).ok, false);
  assert.equal(await h.payment('p'), null);
  assert.deepEqual(await h.authorize('p', 2), { ok: true });
  assert.equal((await h.authorize('p', 1)).ok, false);
  const effs = await h.pendingEffects();
  assert.deepEqual(effs.map((e: any) => [e.from, e.kind, e.data]), [['p', 'card.authorize', { amount: 2 }]]);
  assert.equal((await h.capture('p', 1)).ok, false);
  await h.completeEffect(effs[0].id, 'ok');
  assert.deepEqual(await h.pendingEffects(), []);
  assert.deepEqual(await h.payment('p'), { status: 'authorized', authorized: 2, captured: 0, refunded: 0, requests: 1 });
  assert.equal((await h.capture('p', 3)).ok, false);
  assert.deepEqual(await h.capture('p', 2), { ok: true });
  assert.equal((await h.void('p')).ok, false);
  assert.deepEqual(await h.refund('p', 1), { ok: true });
  assert.equal((await h.refund('p', 2)).ok, false);
  assert.equal((await h.payment('p')).status, 'captured');
  assert.deepEqual(await h.refund('p', 1), { ok: true });
  assert.deepEqual(await h.payment('p'), { status: 'refunded', authorized: 2, captured: 2, refunded: 2, requests: 1 });
  await h.__dispose();
});

test('increase then capture 3', async () => {
  const h = await fresh();
  assert.deepEqual(await h.increase('p'), { ok: false, reason: 'unknown' });
  await h.authorize('p', 2);
  assert.equal((await h.increase('p')).ok, false);
  const [e] = await h.pendingEffects();
  await h.completeEffect(e.id, 'ok');
  assert.equal((await h.capture('p', 3)).ok, false);
  assert.deepEqual(await h.increase('p'), { ok: true });
  assert.equal((await h.increase('p')).ok, false);
  assert.equal((await h.payment('p')).authorized, 3);
  assert.equal((await h.capture('p', 4)).ok, false);
  assert.deepEqual(await h.capture('p', 3), { ok: true });
  assert.equal((await h.increase('p')).ok, false);
  assert.deepEqual(await h.refund('p', 2), { ok: true });
  assert.deepEqual(await h.refund('p', 1), { ok: true });
  assert.deepEqual(await h.payment('p'), { status: 'refunded', authorized: 3, captured: 3, refunded: 3, requests: 1 });
  await h.__dispose();
});

test('expire', async () => {
  const h = await fresh();
  assert.deepEqual(await h.expire('p'), { ok: false, reason: 'unknown' });
  await h.authorize('p', 1);
  assert.equal((await h.expire('p')).ok, false);
  const [e] = await h.pendingEffects();
  await h.completeEffect(e.id, 'ok');
  assert.deepEqual(await h.increase('p'), { ok: true });
  assert.deepEqual(await h.expire('p'), { ok: true });
  assert.deepEqual(await h.payment('p'), { status: 'expired', authorized: 2, captured: 0, refunded: 0, requests: 1 });
  for (const r of [await h.capture('p', 1), await h.void('p'), await h.increase('p'), await h.expire('p'),
    await h.refund('p', 1), await h.timedOut('p'), await h.authorize('p', 1)]) assert.equal(r.ok, false);
  await h.authorize('q', 1);
  const [f] = await h.pendingEffects();
  await h.completeEffect(f.id, 'ok');
  await h.capture('q', 1);
  assert.equal((await h.expire('q')).ok, false);
  assert.equal((await h.payment('q')).status, 'captured');
  await h.__dispose();
});

test('timeouts,late answers, failure', async () => {
  const h = await fresh();
  await h.authorize('p', 1);
  assert.deepEqual(await h.timedOut('p'), { ok: true });
  assert.deepEqual(await h.timedOut('p'), { ok: true });
  assert.equal((await h.pendingEffects()).length, 3);
  assert.deepEqual(await h.timedOut('p'), { ok: true });
  assert.deepEqual(await h.payment('p'), { status: 'failed', authorized: 1, captured: 0, refunded: 0, requests: 3 });
  assert.equal((await h.timedOut('p')).ok, false);
  const effs = await h.pendingEffects();
  await h.completeEffect(effs[0].id, 'ok');
  assert.equal((await h.payment('p')).status, 'failed');
  assert.equal((await h.pendingEffects()).length, 2);
  await h.__dispose();
});

test('decline, then later answer ignored; void', async () => {
  const h = await fresh();
  await h.authorize('a', 1);
  await h.timedOut('a');
  const [e1, e2] = await h.pendingEffects();
  await h.completeEffect(e2.id, 'failed');
  await h.completeEffect(e1.id, 'ok');
  assert.equal((await h.payment('a')).status, 'declined');
  await h.authorize('b', 1);
  const [e] = await h.pendingEffects();
  await h.completeEffect(e.id, 'ok');
  assert.deepEqual(await h.void('b'), { ok: true });
  assert.equal((await h.payment('b')).status, 'voided');
  assert.equal((await h.capture('b', 1)).ok, false);
  await h.__dispose();
});
